<include file="Public:header"/><script type="text/javascript" src="{pigcms{$static_path}js/area_pca.js"></script>		<div class="mainbox">			<div id="nav" class="mainnav_title">				<ul>					<a href="{pigcms{:U('User_behavior/index',['business_type_config'=>-1,'from_type_config'=>-1])}" class="on">购买商品记录</a>					<a href="{pigcms{:U('User_behavior/reply',['business_type_config'=>-1,'from_type_config'=>-1])}">发布评论记录</a>					<a href="{pigcms{:U('User_behavior/appoint',['business_type_config'=>-1,'from_type_config'=>-1])}">预约服务记录</a>					<a href="{pigcms{:U('User_behavior/classify',['business_type_config'=>-1,'from_type_config'=>-1])}">分类信息记录</a>				</ul>			</div>			<table class="search_table" width="100%">				<tr>					<td>						<form action="{pigcms{:U('User_behavior/index')}" method="get">							<input type="hidden" name="c" value="User_behavior"/>							<input type="hidden" name="a" value="index"/>							筛选: <input type="text" name="keyword" class="input-text" value="{pigcms{$_GET['keyword']}"/>							<select name="searchtype">								<option value="goods" <if condition="$_GET['searchtype'] eq 'goods'">selected="selected"</if>>商品名称</option>								<option value="nickname" <if condition="$_GET['searchtype'] eq 'nickname'">selected="selected"</if>>用户昵称</option>								<option value="phone" <if condition="$_GET['searchtype'] eq 'phone'">selected="selected"</if>>用户手机号</option>							</select>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;							<font color="#000">购买日期筛选：</font>							<input type="text" class="input-text" name="begin_time" style="width:120px;" id="d4311"  value="{pigcms{$_GET.begin_time}" onfocus="WdatePicker({readOnly:true,dateFmt:'yyyy-MM-dd'})"/>			   							<input type="text" class="input-text" name="end_time" style="width:120px;" id="d4311" value="{pigcms{$_GET.end_time}" onfocus="WdatePicker({readOnly:true,dateFmt:'yyyy-MM-dd'})"/>							所属业务:							<select name="business_type_config">								<option value="-1">全部</option>									<volist name="business_type_config" id="vo">									<option value="{pigcms{$key}" <if condition="$_GET['business_type_config'] eq $key"> selected="selected"</if>>{pigcms{$vo}</option>									</volist>									</select>								</if>							</select>							购买端口:							<select name="from_type_config">								<option value="-1">全部</option>								<volist name="from_type_config" id="vo">									<option value="{pigcms{$key}" <if condition="$_GET['from_type_config'] eq $key"> selected="selected"</if>>{pigcms{$vo}</option>								</volist>							</select>							</if>							</select>							<input type="submit" style="margin-right:20px;" value="查询" class="button"/>						</form>					</td>				</tr>			</table>			<form name="myform" id="myform" action="" method="post">				<div class="table-list">					<table width="100%" cellspacing="0">						<colgroup>							<col/>							<col/>							<col/>							<col/>							<col/>							<col/>							<col/>							<col width="180" align="center"/>						</colgroup>						<thead>							<tr>								<th>ID</th>								<th>昵称</th>								<th>手机号</th>								<th>商品名称</th>								<th>购买数量</th>								<th class="textcenter">所属业务</th>								<th class="textcenter">购买时间</th>								<th class="textcenter">来源</th>								<th class="textcenter">IP地址</th>							</tr>						</thead>						<tbody>							<if condition="is_array($list)">								<volist name="list" id="vo">									<tr>										<td>{pigcms{$vo.id}</td>										<td>{pigcms{$vo.nickname}</td>										<td>{pigcms{$vo.phone}</td>										<td>{pigcms{$vo.name|default='<font color="#bbb">未知</font>'}</td>										<td>{pigcms{$vo.num|default='1'}</td>										<td class="textcenter">{pigcms{$vo.business_type_text}</td>										<td class="textcenter">{pigcms{$vo.add_time|date='Y-m-d H:i:s',###}</td>										<td class="textcenter">{pigcms{$vo.from_type_text}</td>										<td class="textcenter">{pigcms{$vo.ip}</td>									</tr>								</volist>								<tr><td class="textcenter pagebar" colspan="12">{pigcms{$pagebar}</td></tr>							<else/>								<tr><td class="textcenter red" colspan="12">列表为空！</td></tr>							</if>						</tbody>					</table>				</div>			</form>		</div>		<script>		var url = "{pigcms{$config.site_url}"		var export_url = "{pigcms{:U('User/export')}"</script><script type="text/javascript" src="{pigcms{$static_public}js/export.js"> </script><include file="Public:footer"/>